// VALTREN CRM COMPLETE BROWSER
const CRM_FULL_TABS=[['contacts','Contatos'],['companies','Empresas'],['customers','Clientes'],['leads','Leads'],['interactions','Interações']];
const CRM_FULL_ROLE_OPTIONS=[['customer','Cliente'],['prospect','Prospect'],['partner','Parceiro'],['supplier','Fornecedor'],['service_provider','Prestador']];
const CRM_FULL_STORAGE_PARTIES='valtren.crm.canonical-parties.v1';
const CRM_FULL_STORAGE_DOMAIN='valtren.crm.domain.v1';

function crmFullStoredObject(key,label){
  const saved=localStorage.getItem(key);if(!saved)return null;
  try{const parsed=JSON.parse(saved);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new TypeError(`${label} deve possuir raiz Object`);return parsed;}
  catch(error){console.warn(`CRM: ${label} local não pôde ser restaurado.`,error);return null;}
}
function crmFullStoredObject(key,label){
  const saved=localStorage.getItem(key);if(!saved)return null;
  try{const parsed=JSON.parse(saved);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new TypeError(`${label} deve possuir raiz Object`);return parsed;}
  catch(error){console.warn(`CRM: ${label} local não pôde ser restaurado.`,error);return null;}
}
function crmFullRestorePersistence(){
  if(state.__crmFullPersistenceRestored)return;
  state.__crmFullPersistenceRestored=true;
  if(!state.__crmCanonicalPartyService){
    const parties=crmFullStoredObject(CRM_FULL_STORAGE_PARTIES,'Pessoas/Organizações');
    if(parties){try{state.crmCanonicalParties=ValtrenPartyCore.ensureState(parties);}catch(error){console.warn('CRM: Pessoas/Organizações locais são inválidas.',error);}}
  }
  const domain=crmFullStoredObject(CRM_FULL_STORAGE_DOMAIN,'Domínio CRM');
  if(domain){try{state.crmDomain=ValtrenCrmCore.ensureState(domain);}catch(error){console.warn('CRM: domínio CRM local é inválido.',error);}}
}
function crmFullPersist(){
  try{localStorage.setItem(CRM_FULL_STORAGE_PARTIES,JSON.stringify(state.crmCanonicalParties||{}));localStorage.setItem(CRM_FULL_STORAGE_DOMAIN,JSON.stringify(state.crmDomain||{}));}catch(error){console.warn('CRM: persistência local indisponível.',error);}
}
function crmFullIsLegacyDemo(item){
  const mail=String(item?.email||'').toLowerCase(),id=String(item?.id||'');
  return ['c1','c2','c3','c4','l1','l2','l3'].includes(id)||mail.includes('@exemplo.com')||mail.endsWith('.exemplo');
}
function crmFullService(){
  crmFullRestorePersistence();
  crmRelEnsureState();
  state.crmDomain=ValtrenCrmCore.ensureState(state.crmDomain);
  if(!state.__crmFullService||state.__crmFullService.data!==state.crmDomain){state.__crmFullService=ValtrenCrmCore.createService(crmCanonicalPartyService(),state.crmDomain,{actorProvider:()=>state.crmUserId||state.crmUserName||null});}
  const service=state.__crmFullService;
  if(!service.data.metadata.legacyMigrated){const legacy=crmCanonicalSyncLegacyViews();service.migrateLegacy({...legacy,isDemo:crmFullIsLegacyDemo});crmFullPersist();}
  state.crmFullUi=state.crmFullUi||{includeDemo:false};
  return service;
}
function crmFullUsers(){
  const rows=[],seen=new Set();
  const add=(id,name)=>{id=String(id||'').trim();name=String(name||id||'').trim();if(!id||seen.has(id))return;seen.add(id);rows.push({id,name});};
  const currentId=String(state.crmUserId||'').trim(),currentName=String(state.crmUserName||'').trim();
  if(currentId||currentName)add(currentId||currentName,currentName||currentId);
  (state.crmRefUsers||[]).forEach((u)=>add(u.id||u.email,u.name||u.email));
  return rows;
}
function crmFullResponsibleName(id){return crmFullUsers().find((x)=>x.id===id)?.name||id||'-';}
function crmFullRoleLabel(role){return ValtrenCrmCore.ROLE_LABELS[role]||role||'-';}
function crmFullStageLabel(stage){return ValtrenCrmCore.STAGE_LABELS[stage]||stage||'-';}
function crmFullInteractionLabel(type){return ValtrenCrmCore.INTERACTION_LABELS[type]||type||'-';}
function crmFullDate(value,withTime=true){
  if(!value)return '-';const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value);
  return new Intl.DateTimeFormat('pt-BR',withTime?{dateStyle:'short',timeStyle:'short'}:{dateStyle:'short'}).format(date);
}
function crmFullNowLocal(){const d=new Date(),pad=(n)=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;}
function crmFullSplitTags(value){return String(value||'').split(',').map((x)=>x.trim()).filter(Boolean);}
function crmFullAddressFromData(data){return {line1:String(data.get('addressLine1')||''),number:String(data.get('addressNumber')||''),complement:String(data.get('addressComplement')||''),district:String(data.get('district')||''),city:String(data.get('city')||''),region:String(data.get('region')||''),postalCode:String(data.get('postalCode')||''),country:String(data.get('country')||'BR')};}
function crmFullPartyView(entityType,entityId){
  const service=crmFullService(),party=service.party,entity=party.getEntity(entityType,entityId);if(!entity)return null;
  return {entityType,entity,name:entityType==='person'?entity.fullName:(entity.tradeName||entity.legalName),legalName:entityType==='organization'?entity.legalName:'',email:service.primary(entityType,entityId,'email'),phone:service.primary(entityType,entityId,'phone'),whatsapp:service.primary(entityType,entityId,'whatsapp'),site:service.primary(entityType,entityId,'site'),document:service.document(entityType,entityId,entityType==='person'?'cpf':'cnpj'),address:service.address(entityType,entityId),roles:service.roles(entityType,entityId),context:service.getContext(entityType,entityId,false)};
}
function crmFullLastInteraction(query){return crmFullService().interactionsFor(query)[0]||null;}
function crmFullSearchBlob(parts){return ValtrenCrmCore.fold((parts||[]).filter(Boolean).join(' '));}
function crmFullDemoBadge(isDemo){return isDemo?'<span class="crm-full-demo-badge">Demonstração</span>':'';}
function crmFullRoleBadges(roles){const list=(roles||[]).filter((r)=>ValtrenCrmCore.CRM_ROLE_SET.has(r));return list.length?`<div class="crm-full-badges">${list.map((r)=>`<span>${esc(crmFullRoleLabel(r))}</span>`).join('')}</div>`:'<span class="crm-full-muted">Sem papel adicional</span>';}
function crmFullEmpty(title,description,action=''){return `<div class="crm-full-empty">${icon('users',28)}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;}
function crmFullToast(message,type='success'){
  document.querySelector('.crm-full-toast')?.remove();const el=document.createElement('div');el.className=`crm-full-toast ${type}`;el.setAttribute('role','status');el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),3200);
}
function crmFullError(message){crmFullToast(message,'error');}
function crmFullFormError(form,message){let box=form.querySelector('.crm-full-form-error');if(!box){box=document.createElement('div');box.className='crm-full-form-error';box.setAttribute('role','alert');form.querySelector('.crm-full-modal-body')?.prepend(box);}box.textContent=message;}
function crmFullLegacyId(prefix,existing=''){return existing||`${prefix}${Date.now()}${Math.floor(Math.random()*1000)}`;}
function crmFullPrimaryRole(roles){return (roles||[]).find((r)=>['customer','prospect','partner','supplier','service_provider'].includes(r))||'crm_contact';}
function crmFullRoleToLegacy(role){return {customer:'Cliente',prospect:'Prospect',partner:'Parceiro',supplier:'Fornecedor',service_provider:'Prestador de Serviços',crm_contact:'Contato'}[role]||crmFullRoleLabel(role);}
function crmFullSyncLegacyContact(entityType,entityId,legacyId=''){
  const service=crmFullService(),view=crmFullPartyView(entityType,entityId);if(!view)return '';
  const ctx=service.getContext(entityType,entityId,true),id=crmFullLegacyId('c',legacyId||ctx.legacyId),roles=service.roles(entityType,entityId),rel=entityType==='person'?service.party.data.personOrganizationRelationships.find((x)=>x.personId===entityId&&x.status!=='inactive'):null,org=rel?service.party.getEntity('organization',rel.organizationId):null;
  const item={id,tipo_pessoa:entityType==='organization'?'pessoa_juridica':'pessoa_fisica',name:entityType==='organization'?view.entity.legalName:view.entity.fullName,company:entityType==='organization'?(view.entity.tradeName||''):(org?.tradeName||org?.legalName||''),segment:crmFullRoleToLegacy(crmFullPrimaryRole(roles)),profile:'',phone:view.phone,email:view.email,city:[view.address?.city,view.address?.region].filter(Boolean).join(' / '),responsible:crmFullResponsibleName(ctx.responsibleId),status:ctx.status||'Ativo',priority:ctx.priority||'Média',cpf:entityType==='person'?view.document:'',cnpj:entityType==='organization'?view.document:'',function:rel?.positionTitle||'',address:view.address?.line1||'',notes:ctx.notes||'',interactions:[]};
  if(!crmCanonicalUpsertLegacyRecord('contacts',item,crmCanonicalBinding('crm.contacts',id)?'edit':'create'))throw new Error('Não foi possível atualizar a projeção de compatibilidade do contato.');
  service.patchContext(entityType,entityId,{legacyId:id});return id;
}
function crmFullSyncLegacyLead(lead){
  const service=crmFullService(),person=lead.personId?crmFullPartyView('person',lead.personId):null,org=lead.organizationId?crmFullPartyView('organization',lead.organizationId):null,id=crmFullLegacyId('l',lead.legacyId),entityType=person?'person':'organization';
  const item={id,tipo_pessoa:entityType==='organization'?'pessoa_juridica':'pessoa_fisica',name:person?.name||org?.legalName||org?.name||'',company:org?.name||'',email:person?.email||org?.email||'',phone:person?.phone||org?.phone||'',source:lead.origin||'',stage:crmFullStageLabel(lead.stage),responsible:crmFullResponsibleName(lead.responsibleId),status:lead.status||'Aberto',priority:lead.priority||'Média',notes:lead.notes||''};
  if(!crmCanonicalUpsertLegacyRecord('leads',item,crmCanonicalBinding('crm.leads',id)?'edit':'create'))throw new Error('Não foi possível atualizar a projeção de compatibilidade do lead.');lead.legacyId=id;return id;
}
function crmFullSetManagedRoles(entityType,entityId,selected){
  const service=crmFullService(),managed=['customer','prospect','partner','supplier','service_provider'];selected=new Set(selected||[]);for(const role of managed){if(selected.has(role))service.party.assignRole(entityType,entityId,role,{source:'crm'});else if(service.hasRole(entityType,entityId,role))service.party.removeRole(entityType,entityId,role);}
}
function crmFullPersistAll(){crmCanonicalSyncLegacyViews();crmFullPersist();}

function crmFullSaveContact(payload){
  const service=crmFullService(),result=service.saveContact(payload);crmFullSyncLegacyContact('person',result.person.id,payload.legacyId||result.context.legacyId);crmFullPersistAll();return result;
}
function crmFullSaveCompany(payload){
  const service=crmFullService(),result=service.saveCompany(payload);crmFullSetManagedRoles('organization',result.organization.id,payload.roles||[]);crmFullSyncLegacyContact('organization',result.organization.id,payload.legacyId||result.context.legacyId);crmFullPersistAll();return result;
}
function crmFullSaveCustomer(payload){
  const service=crmFullService(),result=service.saveCustomer(payload);crmFullSyncLegacyContact(result.entityType,result.entity.id,payload.legacyId||result.context.legacyId);crmFullPersistAll();return result;
}
function crmFullSaveLead(payload){
  const service=crmFullService(),lead=service.saveLead(payload);crmFullSyncLegacyLead(lead);if(lead.stage==='converted'&&lead.customerEntityId)crmFullSyncLegacyContact(lead.customerEntityType,lead.customerEntityId);crmFullPersistAll();return lead;
}
function crmFullConvertLead(id){const service=crmFullService(),result=service.convertLead(id);crmFullSyncLegacyLead(result.lead);crmFullSyncLegacyContact(result.customerEntityType,result.customerEntityId);crmFullPersistAll();return result;}
function crmFullArchive(kind,id){
  const service=crmFullService();if(kind==='customer'){const [entityType,entityId]=id.split(':');service.party.removeRole(entityType,entityId,'customer');service.history('customer.removed',{entityType,entityId});crmFullPersistAll();return true;}
  if(kind==='lead'){const lead=service.data.leads.find((x)=>x.id===id);if(!lead)return false;lead.status='archived';lead.updatedAt=new Date().toISOString();service.history('lead.archived',{leadId:id});crmFullPersistAll();return true;}
  if(kind==='interaction'){service.removeInteraction(id);crmFullPersistAll();return true;}
  const entityType=kind==='company'?'organization':'person';const ok=service.archiveEntityContext(entityType,id);crmFullPersistAll();return ok;
}

function crmFullCurrentTab(query){
  const aliases={contatos:'contacts',empresas:'companies',clientes:'customers',interacoes:'interactions','interações':'interactions'};const raw=query?.get('tab')||'contacts',tab=aliases[raw]||raw;return CRM_FULL_TABS.some(([id])=>id===tab)?tab:'contacts';
}
function crmFullTabHref(tab){return `#/crm/relationships?tab=${tab}`;}
function crmFullBreadcrumb(tab){const label=CRM_FULL_TABS.find(([id])=>id===tab)?.[1]||'Contatos';return `<nav class="crm-full-breadcrumb" aria-label="Breadcrumb"><a href="#/crm/relationships">CRM</a><span>/</span><strong>${label}</strong></nav>`;}
function crmFullHeader(tab){
  const config={contacts:['Contatos','Pessoas relacionadas comercial ou institucionalmente à Valtren.','Novo Contato','contact'],companies:['Empresas','Organizações relacionadas à Valtren sem duplicação por papel.','Nova Empresa','company'],customers:['Clientes','Visão de Pessoas e Organizações que possuem o papel Cliente.','Novo Cliente','customer'],leads:['Leads','Oportunidades comerciais vinculadas a identidades canônicas.','Novo Lead','lead'],interactions:['Interações','Histórico real de relacionamento comercial e institucional.','Nova Interação','interaction']},[title,description,actionLabel,kind]=config[tab];
  return `<div class="crm-full-section-header"><div><h2>${title}</h2><p>${description}</p></div><button class="crm-rel-primary" type="button" data-action="crm-full-create" data-kind="${kind}">${icon('plus',16)} ${actionLabel}</button></div>`;
}
function crmFullTabs(tab){return `<nav class="crm-rel-tabs crm-full-tabs" aria-label="Áreas do CRM">${CRM_FULL_TABS.map(([id,label])=>`<a class="${tab===id?'active':''}" href="${crmFullTabHref(id)}">${label}</a>`).join('')}</nav>`;}
function crmFullKpis(items){return `<div class="crm-full-kpis">${items.map(([label,value])=>`<article><span>${esc(label)}</span><strong>${Number(value)||0}</strong></article>`).join('')}</div>`;}
function crmFullDemoToggle(){return `<label class="crm-full-demo-toggle"><input type="checkbox" data-action="crm-full-toggle-demo" ${state.crmFullUi?.includeDemo?'checked':''}> Mostrar dados de demonstração</label>`;}
function crmFullSearchFilters(filters=[]){return `<div class="crm-rel-toolbar crm-full-toolbar"><div class="crm-rel-search"><span>${icon('search',16)}</span><input id="crm-full-search" type="search" placeholder="Buscar no CRM" autocomplete="off"></div>${filters.join('')}${crmFullDemoToggle()}</div>`;}
function crmFullSelectFilter(key,label,options){return `<select data-crm-full-filter="${key}" aria-label="${esc(label)}"><option value="all">${esc(label)}</option>${options.map(([value,text])=>`<option value="${esc(value)}">${esc(text)}</option>`).join('')}</select>`;}
function crmFullTable(title,description,headers,rows,emptyTitle,emptyDescription){
  if(!rows.length)return `<section class="crm-rel-table-card"><div class="crm-rel-list-header"><div><h3>${title}</h3><p>${description}</p></div></div>${crmFullEmpty(emptyTitle,emptyDescription)}</section>`;
  return `<section class="crm-rel-table-card"><div class="crm-rel-list-header"><div><h3>${title}</h3><p>${description}</p></div><span class="crm-rel-count"><b id="crm-full-visible-count">${rows.length}</b> registros</span></div><div class="crm-rel-table-wrap"><table class="crm-rel-table crm-full-table"><thead><tr>${headers.map((h)=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div><div class="crm-rel-pagination crm-full-count-footer"><span>Exibindo <b data-crm-full-visible-footer>${rows.length}</b> registro(s) após os filtros</span></div></section>`;
}
function crmFullActions(kind,id,extra=''){return `<div class="crm-rel-actions"><button type="button" class="crm-rel-more" data-action="crm-full-row-menu" aria-label="Ações">•••</button><div class="crm-rel-actions-menu" hidden><button type="button" data-action="crm-full-view" data-kind="${kind}" data-id="${esc(id)}">Visualizar</button><button type="button" data-action="crm-full-edit" data-kind="${kind}" data-id="${esc(id)}">Editar</button>${extra}<button type="button" class="danger" data-action="crm-full-archive" data-kind="${kind}" data-id="${esc(id)}">${kind==='interaction'?'Arquivar':'Remover do CRM'}</button></div></div>`;}

function crmFullContactsView(){
  const service=crmFullService(),includeDemo=!!state.crmFullUi.includeDemo,rowsData=service.getContacts({includeDemo});
  const real=service.getContacts({includeDemo:false}),customerPF=real.filter(({person})=>service.hasRole('person',person.id,'customer')).length,withCompany=real.filter(({person})=>service.party.data.personOrganizationRelationships.some((r)=>r.personId===person.id&&r.status!=='inactive')).length;
  const rows=rowsData.map(({person,context})=>{const view=crmFullPartyView('person',person.id),rel=service.party.data.personOrganizationRelationships.find((r)=>r.personId===person.id&&r.status!=='inactive'),org=rel?service.party.getEntity('organization',rel.organizationId):null,last=crmFullLastInteraction({personId:person.id,includeDemo}),roles=service.roles('person',person.id),demo=service.isDemoContext('person',person.id),search=crmFullSearchBlob([view.name,view.email,view.phone,view.document,org?.legalName,org?.tradeName,roles.join(' '),(context.tags||[]).join(' ')]);return `<tr data-crm-full-row data-search="${esc(search)}" data-role="${esc(roles.join(' '))}" data-status="${esc(ValtrenCrmCore.fold(context.status))}" data-responsible="${esc(context.responsibleId||'')}" data-priority="${esc(context.priority||'')}"><td><strong>${esc(view.name)}</strong>${crmFullDemoBadge(demo)}</td><td>${esc(org?.tradeName||org?.legalName||'-')}<small>${esc(rel?.positionTitle||rel?.department||'')}</small></td><td><span>${esc(view.phone||'-')}</span><small>${esc(view.email||'-')}</small></td><td>${crmFullRoleBadges(roles)}</td><td>${esc(crmFullResponsibleName(context.responsibleId))}</td><td><span class="crm-rel-status">${esc(context.status||'Ativo')}</span></td><td>${last?`<span>${esc(crmFullInteractionLabel(last.type))}</span><small>${esc(crmFullDate(last.occurredAt))}</small>`:'<span class="crm-full-muted">Sem interação</span>'}</td><td class="crm-rel-actions-cell">${crmFullActions('contact',person.id)}</td></tr>`;});
  const filters=[crmFullSelectFilter('role','Todos os papéis',[['customer','Cliente'],['prospect','Prospect'],['partner','Parceiro'],['supplier','Fornecedor'],['service_provider','Prestador']]),crmFullSelectFilter('status','Todos os status',[['active','Ativo'],['inactive','Inativo'],['negociando','Negociando']]),crmFullSelectFilter('priority','Todas as prioridades',[['high','Alta'],['medium','Média'],['low','Baixa'],['strategic','Estratégico']])];
  return `${crmFullKpis([['Total de Contatos',real.length],['Com empresa',withCompany],['Clientes PF',customerPF]])}${crmFullSearchFilters(filters)}${crmFullTable('Lista de Contatos','Pessoas e seus vínculos comerciais',['Nome','Empresa','Contato','Papéis','Responsável','Status','Última interação','Ações'],rows,'Nenhum contato encontrado','Cadastre o primeiro contato para começar.')}`;
}
