  const rows=rowsData.map(({organization,context})=>{const view=crmFullPartyView('organization',organization.id),roles=service.roles('organization',organization.id),contacts=service.party.getOrganizationContacts(organization.id),primary=contacts.find((x)=>x.relationship.primary)||contacts[0],last=crmFullLastInteraction({organizationId:organization.id,includeDemo}),demo=service.isDemoContext('organization',organization.id),search=crmFullSearchBlob([view.name,view.legalName,view.document,view.email,view.phone,view.site,organization.segment,roles.join(' '),(context.tags||[]).join(' ')]);return `<tr data-crm-full-row data-search="${esc(search)}" data-role="${esc(roles.join(' '))}" data-status="${esc(ValtrenCrmCore.fold(context.status))}" data-responsible="${esc(context.responsibleId||'')}"><td><strong>${esc(view.name)}</strong><small>${esc(view.legalName&&view.legalName!==view.name?view.legalName:'')}</small>${crmFullDemoBadge(demo)}</td><td>${view.document?esc(view.document):'<span class="crm-full-muted">Não informado</span>'}</td><td>${esc(organization.segment||'-')}</td><td>${crmFullRoleBadges(roles)}</td><td>${primary?`<span>${esc(primary.person.fullName)}</span><small>${esc(primary.relationship.positionTitle||primary.relationship.department||'')}</small>`:'<span class="crm-full-muted">Sem contato principal</span>'}</td><td>${esc(crmFullResponsibleName(context.responsibleId))}</td><td><span class="crm-rel-status">${esc(context.status||'Ativo')}</span></td><td>${last?`<span>${esc(crmFullInteractionLabel(last.type))}</span><small>${esc(crmFullDate(last.occurredAt))}</small>`:'<span class="crm-full-muted">Sem interação</span>'}</td><td class="crm-rel-actions-cell">${crmFullActions('company',organization.id)}</td></tr>`;});
  const filters=[crmFullSelectFilter('role','Todos os papéis',[['customer','Cliente'],['prospect','Prospect'],['partner','Parceiro'],['supplier','Fornecedor'],['service_provider','Prestador']]),crmFullSelectFilter('status','Todos os status',[['active','Ativo'],['inactive','Inativo'],['negociando','Negociando']])];
