function crmFullApplyFilters(){
  const query=ValtrenCrmCore.fold(document.getElementById('crm-full-search')?.value||''),filters={};document.querySelectorAll('[data-crm-full-filter]').forEach((el)=>filters[el.dataset.crmFullFilter]=el.value);
  let visible=0;document.querySelectorAll('[data-crm-full-row]').forEach((row)=>{let ok=!query||String(row.dataset.search||'').includes(query);for(const [key,value] of Object.entries(filters)){if(!ok||value==='all')continue;const actual=ValtrenCrmCore.fold(row.dataset[key]||'');ok=key==='role'?actual.split(/\s+/).includes(ValtrenCrmCore.fold(value)):actual===ValtrenCrmCore.fold(value);}row.hidden=!ok;if(ok)visible++;});
  const count=document.getElementById('crm-full-visible-count');if(count)count.textContent=String(visible);document.querySelectorAll('[data-crm-full-visible-footer]').forEach((x)=>x.textContent=String(visible));
}
function crmFullCloseModal(){document.getElementById('crm-full-modal-root')?.remove();}
