function crmFullModalShell(title,subtitle,body,footer=''){return `<div class="crm-full-modal-backdrop" data-action="crm-full-close"></div><section class="crm-full-modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button type="button" data-action="crm-full-close" aria-label="Fechar">×</button></header>${body}${footer}</section>`;}
function crmFullField(label,name,value='',type='text',attrs=''){return `<label class="crm-full-field"><span>${esc(label)}</span><input type="${type}" name="${name}" value="${esc(value||'')}" ${attrs}></label>`;}
function crmFullSelect(label,name,value,options,attrs=''){return `<label class="crm-full-field"><span>${esc(label)}</span><select name="${name}" ${attrs}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
