function crmFullTimeline(items){if(!items.length)return crmFullEmpty('Nenhuma interação registrada','As próximas interações aparecerão aqui.');return `<div class="crm-full-timeline">${items.map((item)=>`<article><span class="crm-full-timeline-dot"></span><time>${esc(crmFullDate(item.occurredAt))}</time><div><strong>${esc(crmFullInteractionLabel(item.type))}</strong><h4>${esc(item.title||'')}</h4><p>${esc(item.description||'')}</p></div></article>`).join('')}</div>`;}
function crmFullHistory(entityType,entityId,leadId=''){const items=crmFullService().data.history.filter((x)=>(entityId&&x.entityType===entityType&&x.entityId===entityId)||(leadId&&x.leadId===leadId)).slice().sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,20);if(!items.length)return crmFullEmpty('Sem histórico comercial','Alterações relevantes do CRM aparecerão aqui.');return `<div class="crm-full-history">${items.map((x)=>`<article><time>${esc(crmFullDate(x.at))}</time><strong>${esc(String(x.action).replaceAll('.',' · '))}</strong></article>`).join('')}</div>`;}
function crmFullDetailModal(kind,id){
  const service=crmFullService();let title='Detalhes',subtitle='CRM',content='';
  if(kind==='contact'){
    const view=crmFullPartyView('person',id),ctx=view?.context,rels=service.party.data.personOrganizationRelationships.filter((x)=>x.personId===id&&x.status!=='inactive'),interactions=service.interactionsFor({personId:id,includeDemo:!!state.crmFullUi.includeDemo});title=view?.name||'Contato';subtitle='Contato · Pessoa canônica';content=`<div class="crm-full-detail-grid">${crmFullDetailCard('Dados cadastrais',`<dl>${crmFullDl('E-mail',view?.email)}${crmFullDl('Telefone',view?.phone)}${crmFullDl('WhatsApp',view?.whatsapp)}${crmFullDl('CPF',view?.document)}${crmFullDl('Status',ctx?.status)}</dl>`)}${crmFullDetailCard('Empresas',rels.length?rels.map((r)=>{const o=service.party.getEntity('organization',r.organizationId);return `<div class="crm-full-linked-row"><strong>${esc(o?.tradeName||o?.legalName||'-')}</strong><span>${esc(r.positionTitle||r.department||'-')}</span></div>`;}).join(''):crmFullEmpty('Sem empresa vinculada','Este contato ainda não possui vínculo com empresa.'))}${crmFullDetailCard('Papéis',crmFullRoleBadges(service.roles('person',id)))}${crmFullDetailCard('Histórico',crmFullHistory('person',id))}${crmFullDetailCard('Interações',crmFullTimeline(interactions),'wide')}</div>`;
  }else if(kind==='company'){
    const view=crmFullPartyView('organization',id),ctx=view?.context,contacts=service.party.getOrganizationContacts(id),interactions=service.interactionsFor({organizationId:id,includeDemo:!!state.crmFullUi.includeDemo});title=view?.name||'Empresa';subtitle='Empresa · Organização canônica';content=`<div class="crm-full-detail-grid">${crmFullDetailCard('Dados cadastrais',`<dl>${crmFullDl('Razão social',view?.legalName)}${crmFullDl('CNPJ',view?.document)}${crmFullDl('E-mail',view?.email)}${crmFullDl('Telefone',view?.phone)}${crmFullDl('Site',view?.site)}${crmFullDl('Status',ctx?.status)}</dl>`)}${crmFullDetailCard('Contatos',contacts.length?contacts.map(({relationship,person})=>`<div class="crm-full-linked-row"><strong>${esc(person.fullName)}</strong><span>${esc(relationship.positionTitle||relationship.department||'-')}</span></div>`).join(''):crmFullEmpty('Sem contatos vinculados','Vincule Pessoas canônicas à empresa.'))}${crmFullDetailCard('Papéis',crmFullRoleBadges(service.roles('organization',id)))}${crmFullDetailCard('Histórico',crmFullHistory('organization',id))}${crmFullDetailCard('Interações',crmFullTimeline(interactions),'wide')}</div>`;
  }else if(kind==='customer'){
    const [entityType,entityId]=id.split(':'),view=crmFullPartyView(entityType,entityId),contacts=entityType==='organization'?service.party.getOrganizationContacts(entityId):[],interactions=service.interactionsFor(entityType==='person'?{personId:entityId,customerEntityType:'person',customerEntityId:entityId,includeDemo:!!state.crmFullUi.includeDemo}:{organizationId:entityId,customerEntityType:'organization',customerEntityId:entityId,includeDemo:!!state.crmFullUi.includeDemo});title=view?.name||'Cliente';subtitle=`Cliente · ${entityType==='person'?'Pessoa Física':'Pessoa Jurídica'}`;content=`<div class="crm-full-detail-grid">${crmFullDetailCard('Dados cadastrais',`<dl>${crmFullDl('Documento',view?.document)}${crmFullDl('E-mail',view?.email)}${crmFullDl('Telefone',view?.phone)}${crmFullDl('Status',view?.context?.status)}</dl>`)}${crmFullDetailCard('Contatos',entityType==='organization'?(contacts.length?contacts.map(({relationship,person})=>`<div class="crm-full-linked-row"><strong>${esc(person.fullName)}</strong><span>${esc(relationship.positionTitle||relationship.department||'-')}</span></div>`).join(''):crmFullEmpty('Sem contatos vinculados','Nenhuma Pessoa está vinculada a esta empresa.')):'<p class="crm-full-muted">Cliente Pessoa Física.</p>')}${crmFullDetailCard('Histórico',crmFullHistory(entityType,entityId))}${crmFullDetailCard('Interações',crmFullTimeline(interactions),'wide')}${crmFullFutureSections()}</div>`;
  }else if(kind==='lead'){
    const lead=service.data.leads.find((x)=>x.id===id),identity=lead?crmFullLeadIdentity(lead):{},interactions=lead?service.interactionsFor({leadId:id,includeDemo:!!state.crmFullUi.includeDemo}):[];title=identity.name||'Lead';subtitle=`Lead · ${lead?crmFullStageLabel(lead.stage):''}`;content=lead?`<div class="crm-full-detail-grid">${crmFullDetailCard('Identidade',`<dl>${crmFullDl('Pessoa',identity.person?.name)}${crmFullDl('Empresa',identity.organization?.name)}${crmFullDl('E-mail',identity.email)}${crmFullDl('Telefone',identity.phone)}</dl>`)}${crmFullDetailCard('Oportunidade',`<dl>${crmFullDl('Origem',lead.origin)}${crmFullDl('Etapa',crmFullStageLabel(lead.stage))}${crmFullDl('Prioridade',lead.priority)}${crmFullDl('Responsável',crmFullResponsibleName(lead.responsibleId))}${crmFullDl('Produto de interesse',lead.productInterestRef)}${crmFullDl('Serviço de interesse',lead.serviceInterestRef)}${crmFullDl('Convertido em',lead.convertedAt?crmFullDate(lead.convertedAt):'Não')}</dl>`)}${crmFullDetailCard('Histórico',crmFullHistory('', '', lead.id))}${crmFullDetailCard('Interações',crmFullTimeline(interactions),'wide')}</div>`:crmFullEmpty('Lead não encontrado','O registro solicitado não está disponível.');
  }else if(kind==='interaction'){
    const item=service.data.interactions.find((x)=>x.id===id);title=item?.title||'Interação';subtitle=item?crmFullInteractionLabel(item.type):'Interação';content=item?`<div class="crm-full-detail-grid">${crmFullDetailCard('Dados',`<dl>${crmFullDl('Tipo',crmFullInteractionLabel(item.type))}${crmFullDl('Data',crmFullDate(item.occurredAt))}${crmFullDl('Relacionado a',crmFullInteractionTargetLabel(item))}${crmFullDl('Responsável',crmFullResponsibleName(item.responsibleId))}${crmFullDl('Status',item.status)}${crmFullDl('Follow-up',item.followUpAt?crmFullDate(item.followUpAt):'—')}</dl>`)}${crmFullDetailCard('Descrição',`<p>${esc(item.description||'Sem descrição.')}</p>`,'wide')}</div>`:crmFullEmpty('Interação não encontrada','O registro solicitado não está disponível.');
  }
  return crmFullModalShell(title,subtitle,`<div class="crm-full-modal-body crm-full-detail-body">${content}</div><footer><button type="button" class="crm-rel-secondary" data-action="crm-full-close">Fechar</button></footer>`);
}
function crmFullDl(label,value){return `<div><dt>${esc(label)}</dt><dd>${value?esc(value):'<span class="crm-full-muted">Não informado</span>'}</dd></div>`;}
function crmFullDetailCard(title,content,cls=''){return `<section class="crm-full-detail-card ${cls}"><h3>${esc(title)}</h3>${content}</section>`;}
function crmFullFutureSections(){return `<section class="crm-full-detail-card wide crm-full-future"><h3>Integrações futuras</h3><div>${[['Produtos relacionados','Negócios'],['Serviços relacionados','Negócios'],['Contratos','Jurídico'],['Transações e Notas Fiscais','Financeiro'],['Atendimentos','ValtrenChat']].map(([label,owner])=>`<article><strong>${label}</strong><span>Sem dados · Owner: ${owner}</span></article>`).join('')}</div></section>`;}

function crmFullCustomerToggle(){const control=document.querySelector('[name="entityType"]');if(!control)return;const type=control.value||'person';document.querySelectorAll('[data-customer-group]').forEach((el)=>el.hidden=el.dataset.customerGroup!==type);}
function crmFullParseTarget(value){const parts=String(value||'').split(':');if(parts[0]==='person')return {personId:parts[1]||''};if(parts[0]==='organization')return {organizationId:parts[1]||''};if(parts[0]==='lead')return {leadId:parts[1]||''};if(parts[0]==='customer')return {customerEntityType:parts[1]||'',customerEntityId:parts[2]||''};return {};}
function crmFullSerializeForm(form){
  const data=new FormData(form),kind=form.dataset.kind,id=form.dataset.id||'',address=crmFullAddressFromData(data),common={responsibleId:String(data.get('responsibleId')||''),status:String(data.get('status')||'active'),priority:String(data.get('priority')||'medium'),notes:String(data.get('notes')||''),tags:crmFullSplitTags(data.get('tags')),address};
  if(kind==='contact')return {kind,payload:{...common,personId:id||'',legacyId:id?crmFullService().getContext('person',id,false)?.legacyId||'':'',fullName:String(data.get('fullName')||''),cpf:String(data.get('cpf')||''),email:String(data.get('email')||''),phone:String(data.get('phone')||''),whatsapp:String(data.get('whatsapp')||''),role:String(data.get('role')||'crm_contact'),source:String(data.get('source')||''),organizationId:String(data.get('organizationId')||''),organizationName:String(data.get('organizationName')||''),positionTitle:String(data.get('positionTitle')||''),department:String(data.get('department')||'')}};
  if(kind==='company')return {kind,payload:{...common,organizationId:id||'',legacyId:id?crmFullService().getContext('organization',id,false)?.legacyId||'':'',legalName:String(data.get('legalName')||''),tradeName:String(data.get('tradeName')||''),cnpj:String(data.get('cnpj')||''),segment:String(data.get('segment')||''),organizationType:String(data.get('organizationType')||''),email:String(data.get('email')||''),phone:String(data.get('phone')||''),site:String(data.get('site')||''),roles:data.getAll('roles')}};
  if(kind==='customer'){const entityType=String(data.get('entityType')||'person'),parts=id.split(':'),existingId=parts[1]||'',entityId=entityType==='person'?String(data.get('existingPersonId')||existingId):String(data.get('existingOrganizationId')||existingId);return {kind,payload:{...common,entityType,entityId,fullName:String(data.get('fullName')||''),cpf:String(data.get('cpf')||''),email:entityType==='person'?String(data.get('email')||''):String(data.get('organizationEmail')||''),phone:entityType==='person'?String(data.get('phone')||''):String(data.get('organizationPhone')||''),legalName:String(data.get('legalName')||''),tradeName:String(data.get('tradeName')||''),cnpj:String(data.get('cnpj')||'')}};}
  if(kind==='lead')return {kind,payload:{leadId:id||'',identityMode:String(data.get('identityMode')||'person'),fullName:String(data.get('fullName')||''),email:String(data.get('email')||''),phone:String(data.get('phone')||''),cpf:String(data.get('cpf')||''),organizationName:String(data.get('organizationName')||''),tradeName:String(data.get('tradeName')||''),cnpj:String(data.get('cnpj')||''),origin:String(data.get('origin')||''),responsibleId:common.responsibleId,stage:String(data.get('stage')||'new'),priority:common.priority,status:String(data.get('status')||'open'),productInterestRef:String(data.get('productInterestRef')||''),serviceInterestRef:String(data.get('serviceInterestRef')||''),notes:common.notes}};
  if(kind==='interaction')return {kind,payload:{interactionId:id||'',type:String(data.get('type')||'note'),title:String(data.get('title')||''),description:String(data.get('description')||''),occurredAt:String(data.get('occurredAt')||'')||new Date().toISOString(),responsibleId:common.responsibleId,status:String(data.get('status')||'completed'),followUpAt:String(data.get('followUpAt')||''),...crmFullParseTarget(data.get('target'))}};
  return {kind,payload:{}};
}
function crmFullValidate(kind,payload){
  if(kind==='contact'&&!payload.fullName.trim())return 'Informe o nome do contato.';
  if(kind==='company'&&!payload.legalName.trim())return 'Informe a razão social ou nome da empresa.';
  if(kind==='customer'){if(payload.entityType==='person'&&!payload.entityId&&!payload.fullName.trim())return 'Selecione uma Pessoa existente ou informe o nome.';if(payload.entityType==='organization'&&!payload.entityId&&!payload.legalName.trim())return 'Selecione uma Empresa existente ou informe a razão social.';}
  if(kind==='lead'){if(payload.identityMode!=='organization'&&!payload.fullName.trim())return 'Informe a Pessoa relacionada ao lead.';if(payload.identityMode!=='person'&&!payload.organizationName.trim())return 'Informe a Empresa relacionada ao lead.';}
  if(kind==='interaction'){if(!payload.title.trim())return 'Informe o título/resumo da interação.';if(!payload.personId&&!payload.organizationId&&!payload.leadId&&!payload.customerEntityId)return 'Selecione a entidade relacionada.';}
  return '';
}
function crmFullSubmit(form){
  const {kind,payload}=crmFullSerializeForm(form),error=crmFullValidate(kind,payload);if(error){crmFullFormError(form,error);return;}
  try{
    if(kind==='contact')crmFullSaveContact(payload);else if(kind==='company')crmFullSaveCompany(payload);else if(kind==='customer')crmFullSaveCustomer(payload);else if(kind==='lead')crmFullSaveLead(payload);else if(kind==='interaction'){const service=crmFullService();if(payload.interactionId)service.updateInteraction(payload.interactionId,payload);else service.createInteraction(payload);crmFullPersistAll();}
    crmFullCloseModal();renderCurrentWithoutReset();crmFullToast('Alterações salvas com sucesso.');
  }catch(error){crmFullFormError(form,error?.message||'Não foi possível salvar.');}
}

if(!window.__valtrenCrmCompleteBound){
  window.__valtrenCrmCompleteBound=true;
  document.addEventListener('click',(event)=>{
    const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
    if(action==='crm-full-row-menu'){event.stopPropagation();const menu=target.parentElement?.querySelector('.crm-rel-actions-menu');document.querySelectorAll('.crm-rel-actions-menu').forEach((x)=>{if(x!==menu)x.hidden=true;});if(menu)menu.hidden=!menu.hidden;return;}
    if(action==='crm-full-create'){crmFullOpenModal(target.dataset.kind||'contact','create');return;}
    if(action==='crm-full-view'){crmFullOpenModal(target.dataset.kind||'contact','view',target.dataset.id||'');return;}
    if(action==='crm-full-edit'){crmFullOpenModal(target.dataset.kind||'contact','edit',target.dataset.id||'');return;}
    if(action==='crm-full-close'){crmFullCloseModal();return;}
    if(action==='crm-full-toggle-demo'){state.crmFullUi=state.crmFullUi||{};state.crmFullUi.includeDemo=!!target.checked;renderCurrentWithoutReset();return;}
    if(action==='crm-full-convert'){if(confirm('Converter este lead em Cliente preservando identidade e histórico?')){try{crmFullConvertLead(target.dataset.id||'');renderCurrentWithoutReset();crmFullToast('Lead convertido em Cliente.');}catch(error){crmFullError(error?.message||'Não foi possível converter o lead.');}}return;}
    if(action==='crm-full-archive'){const kind=target.dataset.kind,id=target.dataset.id;if(confirm(kind==='customer'?'Remover o papel Cliente sem apagar a identidade canônica?':'Remover este contexto do CRM sem apagar a identidade canônica?')){crmFullArchive(kind,id);crmFullCloseModal();renderCurrentWithoutReset();crmFullToast('Contexto removido sem destruir a identidade canônica.');}return;}
  });
  document.addEventListener('input',(event)=>{if(event.target?.id==='crm-full-search')crmFullApplyFilters();});
  document.addEventListener('change',(event)=>{
    if(event.target?.matches?.('[data-crm-full-filter]'))crmFullApplyFilters();
    if(event.target?.matches?.('[data-crm-full-customer-type]'))crmFullCustomerToggle();
  });
  document.addEventListener('submit',(event)=>{if(event.target?.id==='crm-full-form'){event.preventDefault();crmFullSubmit(event.target);}});
  document.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&document.getElementById('crm-full-modal-root'))crmFullCloseModal();});
}